bench_run = function(d) {
  set.seed(1L)
  hist = d$dat[seq_len(d$t0), , drop = FALSE]
  imp = suppressWarnings(missRanger::missRanger(hist, verbose = 0, num.threads = 1L, keep_forests = TRUE))
  out = numeric(d$k)
  for (j in seq_len(d$k)) {
    nd = d$dat[d$t0 + j, , drop = FALSE]
    out[j] = as.numeric(suppressWarnings(stats::predict(imp, nd))$x1)
  }
  out
}
